const state={space:'windowsill',light:'sunny'};const spaceLabels={windowsill:'sill',balcony:'balcony',rooftop:'rooftop'};const plants={sunny:{windowsill:['basil','thyme','compact marigolds'],balcony:['rosemary','oregano','nasturtiums'],rooftop:['lavender','thyme','dwarf sunflowers']},partial:{windowsill:['mint','parsley','chives'],balcony:['lettuce','chives','calendula'],rooftop:['kale','parsley','calendula']},shade:{windowsill:['ferns','moss','a shade-loving violet'],balcony:['ferns','mint','woodland strawberries'],rooftop:['ferns','woodland strawberries','chives']}};function update(){document.querySelectorAll('[data-group]').forEach(b=>{let on=state[b.dataset.group]===b.dataset.value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});let p=plants[state.light][state.space];let lightLabel={sunny:'sunny',partial:'part-shade',shade:'shady'}[state.light];document.querySelector('#resultTitle').textContent=`The ${lightLabel} ${spaceLabels[state.space]}`;document.querySelector('#resultText').textContent=`Imagine ${p[0]}, ${p[1]}, and ${p[2]} bringing a little life to your ${state.space}.`;document.querySelector('#resultTags').textContent=p.join(' / ').toUpperCase()}document.addEventListener('click',e=>{let b=e.target.closest('[data-group]');if(!b)return;state[b.dataset.group]=b.dataset.value;update()});document.querySelector('#reset').addEventListener('click',()=>{state.space='windowsill';state.light='sunny';update()});update();
